/* @author MILO-GAO(高振銘)@2020 */ package page2020.anno;import java.lang.reflect.Field;import java.util.ArrayList;import java.util.List;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.core.Prop;import page2020.util.EmptyUtil;public class DataProp<T, C extends DataItem<C>> extends Prop<T, C> {	private static Logger log = LoggerFactory.getLogger(DataProp.class);	private Class<?> clazz;	private List<String> dataKeys = new ArrayList<String>();	private List<Field> displayFields = new ArrayList<Field>();	private List<String> displayNames = new ArrayList<String>();	private List<C> cache = new ArrayList<C>();	private List<C> storage = new ArrayList<C>();	public DataProp(Class<?> clazz) {		this.clazz = clazz;	}	protected void base(String name) {		if (EmptyUtil.not(name)) {			super.name(name);		}		if (EmptyUtil.is(super.getName())) {			String dataName = App.className(this.clazz);			if (dataName != null) {				super.name(dataName);			} else {				log.error("DataProp: '" + this.clazz.getCanonicalName() + "' is NOT in messages.properties !");			}		}	}	protected void cache(C item) {		if (EmptyUtil.not(item.getName())) {			this.cache.add(item);		}	}	protected void storage() {		if (EmptyUtil.is(this.cache)) {			return;		}		List<C> buffer = this.cache;		this.cache = new ArrayList<C>();		if (! this.storage.isEmpty()) {			buffer.addAll(this.storage);		}		this.storage = buffer;	}	protected void sorting() {		if (EmptyUtil.is(this.storage)) {			return;		}		List<C> zeroList = new ArrayList<C>();			List<C> indexList = new ArrayList<C>();			List<Integer> indexes = new ArrayList<Integer>();			this.storage.forEach(item -> {			if (item.getIndex() == 0) {				zeroList.add(item);			} else {				indexList.add(item);				indexes.add(Integer.valueOf(item.getIndex()));			}		});		List<C> buffer = new ArrayList<C>();		if (! zeroList.isEmpty()) {			buffer.addAll(zeroList);		}		if (! indexList.isEmpty()) {			indexes.forEach(integer -> {				C item = indexList.remove(0);				int index = integer.intValue() - 1;				int size = buffer.size();				if (index >= size) {					buffer.add(item);				} else {					boolean inserted = false;					for (int i=index; i < size; i++) {						int targetIndex = buffer.get(i).getIndex();						if (targetIndex == 0 || (targetIndex - 1) > index) {							buffer.add(i, item);							inserted = true;							break;						}					}					if (! inserted) {						buffer.add(item);					}				}			});		}		buffer.forEach(item -> {			super.add(item.getName(), item);			if (item.isKey()) {				Field field = item.getField();				this.dataKeys.add(field.getName());						if (! item.isHidden()) {					this.displayFields.add(field);							this.displayNames.add(item.getFieldName());						}			}		});		this.cache = null;		this.storage = null;	}	public Class<?> getClazz() {		return clazz;	}	public void setClazz(Class<?> clazz) {		this.clazz = clazz;	}	public List<String> getDataKeys() {		return dataKeys;	}	public List<Field> getDisplayFields() {		return displayFields;	}	public List<String> getDisplayNames() {		return displayNames;	}}